function loadBoard() {
    const storedData = localStorage.getItem(STORAGE_KEY);
    if (storedData) {
        kabanBoardState = JSON.parse(storedData);
    } else {
        // Inicialización de datos si no hay nada guardado
        kabanBoardState = {
            'pendiente': [], 
            'encourso': [], 
            'completado': []
        };
    }
    renderAllCards();
}
