function renderAllCards() {
    // 1. Limpiar contenedores existentes
    ['pendiente', 'encourso', 'completado'].forEach(status => {
        document.getElementById(`cards-contenedor-${status}`).innerHTML = '';
    });

    // Definición de orden de prioridad (Alta > Media > Baja)
    const priorityOrder = { 'alta': 3, 'media': 2, 'baja': 1 };

    // 2. Renderizar tarjetas y actualizar contadores
    for (const status in kabanBoardState) {
        let containerEl = document.getElementById(`cards-contenedor-${status}`);
        let countSpan = document.querySelector(`#${status} .card-count`);

        if (!containerEl || !countSpan) continue;

        // 1. Obtener y ordenar las tarjetas según R16: Prioridad (descendente) -> Recencia (descendente)
        let cards = kabanBoardState[status];
        cards.sort((a, b) => {
            // Asumimos que el objeto card tiene una propiedad 'priority' para cumplir con R16
            const priorityA = priorityOrder[a.priority] || 0;
            const priorityB = priorityOrder[b.priority] || 0;

            // Comparar prioridad (descendente: B - A)
            if (priorityA !== priorityB) {
                return priorityB - priorityA;
            }

            // Si la prioridad es igual, comparar por ID/Timestamp (descendente: más grande = más reciente)
            const idA = parseInt(a.id);
            const idB = parseInt(b.id);
            return idB - idA; 
        });

        // Renderizar cada tarjeta del estado en su contenedor correspondiente (usando el array ordenado)
        cards.forEach(card => {
            const cardElement = createCardElement(card);
            containerEl.appendChild(cardElement);
        });

        // Actualizar el contador de la columna
        countSpan.textContent = `(${kabanBoardState[status].length})`;
    }
}
